#include <format>
#include <string>
#include <vector>

struct Line
{
    std::string item{};
    int quantity{};
    int centsEach{};
};

std::string receipt(const std::vector<Line>& lines)
{
    std::string text{ std::format("{:<12}{:>5}{:>10}\n", "Item", "Qty", "Total") };
    long long grand{ 0 };
    for (const Line& line : lines)
    {
        const long long total{ static_cast<long long>(line.quantity) * line.centsEach };
        grand += total;
        text += std::format("{:<12}{:>5}{:>10.2f}\n", line.item, line.quantity, static_cast<double>(total) / 100.0);
    }
    text += std::format("{:-<27}\n", "");
    text += std::format("{:<17}{:>10.2f}\n", "TOTAL", static_cast<double>(grand) / 100.0);
    return text;
}

unitTests:
TEST("two lines") {
    CHECK_EQ(receipt({ { "Coffee", 2, 350 }, { "Bagel", 1, 225 } }),
        "Item          Qty     Total\n"
        "Coffee          2      7.00\n"
        "Bagel           1      2.25\n"
        "---------------------------\n"
        "TOTAL                  9.25\n");
}
TEST("an empty receipt still has a header and a total") {
    CHECK_EQ(receipt({}),
        "Item          Qty     Total\n"
        "---------------------------\n"
        "TOTAL                  0.00\n");
}
TEST("large amounts") { const std::string r{ receipt({ { "Laptop", 3, 129999 } }) }; CHECK(r.find("Laptop          3   3899.97\n") != std::string::npos); CHECK(r.find("TOTAL               3899.97\n") != std::string::npos); }

